28	ColumnsDescription getStructureOfRemoteTableInShard(
29	    const Cluster & cluster,
30	    const Cluster::ShardInfo & shard_info,
31	    const StorageID & table_id,
32	    ContextPtr context,
33	    const ASTPtr & table_func_ptr)
34	{
35	    String query;
36	
37	    if (table_func_ptr)
38	    {
39	        if (shard_info.isLocal())
40	        {
41	            TableFunctionPtr table_function_ptr = TableFunctionFactory::instance().get(table_func_ptr, context);
42	            return table_function_ptr->getActualTableStructure(context);
43	        }
44	
45	        auto table_func_name = queryToString(table_func_ptr);
46	        query = "DESC TABLE " + table_func_name;
47	    }
48	    else
49	    {
50	        if (shard_info.isLocal())
51	        {
52	            auto storage_ptr = DatabaseCatalog::instance().getTable(table_id, context);
53	            return storage_ptr->getInMemoryMetadataPtr()->getColumns();
54	        }
55	
56	        /// Request for a table description
57	        query = "DESC TABLE " + table_id.getFullTableName();
58	    }
59	
60	    ColumnsDescription res;
61	    auto new_context = ClusterProxy::updateSettingsForCluster(cluster, context, context->getSettingsRef());
62	
63	    /// Expect only needed columns from the result of DESC TABLE. NOTE 'comment' column is ignored for compatibility reasons.
64	    Block sample_block
65	    {
66	        { ColumnString::create(), std::make_shared<DataTypeString>(), "name" },
67	        { ColumnString::create(), std::make_shared<DataTypeString>(), "type" },
68	        { ColumnString::create(), std::make_shared<DataTypeString>(), "default_type" },
69	        { ColumnString::create(), std::make_shared<DataTypeString>(), "default_expression" },
70	    };
71	
72	    /// Execute remote query without restrictions (because it's not real user query, but part of implementation)
73	    RemoteQueryExecutor executor(shard_info.pool, query, sample_block, new_context);
74	    executor.setPoolMode(PoolMode::GET_ONE);
75	    if (!table_func_ptr)
76	        executor.setMainTable(table_id);
77	
78	    const DataTypeFactory & data_type_factory = DataTypeFactory::instance();
79	
80	    ParserExpression expr_parser;
81	
82	    while (Block current = executor.read())
83	    {
84	        ColumnPtr name = current.getByName("name").column;
85	        ColumnPtr type = current.getByName("type").column;
86	        ColumnPtr default_kind = current.getByName("default_type").column;
87	        ColumnPtr default_expr = current.getByName("default_expression").column;
88	        size_t size = name->size();
89	
90	        for (size_t i = 0; i < size; ++i)
91	        {
92	            ColumnDescription column;
93	
94	            column.name = (*name)[i].get<const String &>();
95	
96	            String data_type_name = (*type)[i].get<const String &>();
97	            column.type = data_type_factory.get(data_type_name);
98	
99	            String kind_name = (*default_kind)[i].get<const String &>();
100	            if (!kind_name.empty())
101	            {
102	                column.default_desc.kind = columnDefaultKindFromString(kind_name);
103	                String expr_str = (*default_expr)[i].get<const String &>();
104	                column.default_desc.expression = parseQuery(
105	                    expr_parser, expr_str.data(), expr_str.data() + expr_str.size(), "default expression", 0, context->getSettingsRef().max_parser_depth);
106	            }
107	
108	            res.add(column);
109	        }
110	    }
111	
112	    executor.finish();
113	    return res;
114	}
