116	ColumnsDescription getStructureOfRemoteTable(
117	    const Cluster & cluster,
118	    const StorageID & table_id,
119	    ContextPtr context,
120	    const ASTPtr & table_func_ptr)
121	{
122	    const auto & shards_info = cluster.getShardsInfo();
123	
124	    std::string fail_messages;
125	
126	    for (const auto & shard_info : shards_info)
127	    {
128	        try
129	        {
130	            const auto & res = getStructureOfRemoteTableInShard(cluster, shard_info, table_id, context, table_func_ptr);
131	
132	            /// Expect at least some columns.
133	            /// This is a hack to handle the empty block case returned by Connection when skip_unavailable_shards is set.
134	            if (res.empty())
135	                continue;
136	
137	            return res;
138	        }
139	        catch (const NetException &)
140	        {
141	            std::string fail_message = getCurrentExceptionMessage(false);
142	            fail_messages += fail_message + '\n';
143	            continue;
144	        }
145	    }
146	
147	    throw NetException(
148	        "All attempts to get table structure failed. Log: \n\n" + fail_messages + "\n",
149	        ErrorCodes::NO_REMOTE_SHARD_AVAILABLE);
150	}
