#pragma once

#include "ICommand.h"
#include <Interpreters/Context.h>

namespace DB
{

namespace ErrorCodes
{
    extern const int BAD_ARGUMENTS;
}

class CommandMkdir : public ICommand
{
public:
    CommandMkdir()
    {
        command_name = "mkdir";
        description = "Create directory\nPath should be in format './' or './path' or 'path'";
        usage = "mkdir [OPTION]... <PATH>";
    }

    void processOptions(
        Poco::Util::LayeredConfiguration &,
        po::variables_map &) const override
    {}

    void execute(
        const std::vector<String> & command_arguments,
        DB::ContextMutablePtr & global_context,
        Poco::Util::LayeredConfiguration & config) override
    {
        if (command_arguments.size() != 1)
        {
            printHelpMessage();
            throw DB::Exception("Bad Arguments", DB::ErrorCodes::BAD_ARGUMENTS);
        }

        String disk_name = config.getString("disk", "default");

        String path = command_arguments[0];

        DiskPtr disk = global_context->getDisk(disk_name);

        String relative_path = relativePathWithValidate(path);

        disk->createDirectories(relative_path);
    }
};
}

std::unique_ptr <DB::ICommand> makeCommandMkdir()
{
    return std::make_unique<DB::CommandMkdir>();
}

